import React, { useState } from 'react';
import { TabMenu } from 'primereact/tabmenu';
import { Button } from 'primereact/button';

export default function Controlled() {
    const [activeIndex, setActiveIndex] = useState(3);
    const items = [
        { label: 'Dashboard', icon: 'pi pi-home' },
        { label: 'Transactions', icon: 'pi pi-chart-line' },
        { label: 'Products', icon: 'pi pi-list' },
        { label: 'Messages', icon: 'pi pi-inbox' }
    ];

    return (
        <>
            <div className="fxb fhe gp2 mgb8">
                <Button onClick={() => setActiveIndex(0)} className="w32 h32 pd0" rounded outlined={activeIndex !== 0} label="1" />
                <Button onClick={() => setActiveIndex(1)} className="w32 h32 pd0" rounded outlined={activeIndex !== 1} label="2" />
                <Button onClick={() => setActiveIndex(2)} className="w32 h32 pd0" rounded outlined={activeIndex !== 2} label="3" />
                <Button onClick={() => setActiveIndex(3)} className="w32 h32 pd0" rounded outlined={activeIndex !== 3} label="4" />
            </div>
            <TabMenu model={items} activeIndex={activeIndex} onTabChange={(e) => setActiveIndex(e.index)} />
         </>
    )

}